package com.vault.repository;import com.vault.entity.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import org.springframework.transaction.annotation.Transactional;import java.util.*;public interface ActivityLogRepository extends JpaRepository<ActivityLog,UUID>{List<ActivityLog> findTop100ByUserIdOrderByCreatedAtDesc(UUID userId);@Modifying @Transactional @Query("update ActivityLog a set a.apiKey = null where a.apiKey = :key") void detachKey(@Param("key") ApiKey key);}
